(function () {
  "use strict";

  var DEFAULT_COLORS = {
    concept: "#3b82f6",
    tool: "#22c55e",
    decision: "#f59e0b",
    error: "#ef4444",
    service: "#8b5cf6",
    person: "#10b981",
    incident: "#f43f5e",
    reference: "#94a3b8",
  };
  var FALLBACK_COLOR = "#64748b";

  var instances = new Map();
  var pendingData = new Map();

  function getColor(colorMap, type) {
    return colorMap[type] || DEFAULT_COLORS[type] || FALLBACK_COLOR;
  }

  // showError replaces the spinner with a visible message in the widget's
  // error box and logs the cause, so a broken graph never looks like an
  // empty one.
  function showError(el, msg, err) {
    console.error("graphwidget #" + el.id + ": " + msg, err === undefined ? "" : err);
    el.setAttribute("data-tui-graph-failed", "true");
    var loading = el.querySelector("[data-tui-graph-loading]");
    if (loading) loading.style.display = "none";
    var box = el.querySelector("[data-tui-graph-error]");
    if (box) {
      box.textContent = msg;
      box.hidden = false;
    }
  }

  // checkData accepts graph JSON with a nodes array (links optional) and
  // throws otherwise.
  function checkData(data) {
    if (!data || !Array.isArray(data.nodes)) {
      throw new Error("graph JSON has no nodes array");
    }
    if (data.links === undefined) data.links = [];
    if (!Array.isArray(data.links)) {
      throw new Error("graph JSON links is not an array");
    }
    return data;
  }

  function init() {
    document
      .querySelectorAll("[data-tui-graph]:not([data-tui-graph-initialized])")
      .forEach(function (el) {
        var id = el.id;
        if (!id) return;
        el.setAttribute("data-tui-graph-initialized", "true");
        if (typeof ForceGraph3D !== "function") {
          showError(el, "Graph library failed to load (3d-force-graph.min.js missing).");
          return;
        }
        try {
          initGraph(el, id);
        } catch (err) {
          showError(el, "Graph failed to start: " + (err && err.message ? err.message : err), err);
        }
      });
  }

  // initGraph builds one graph; anything it throws becomes the widget's
  // error state (see init).
  function initGraph(el, id) {
    var dataURL = el.getAttribute("data-tui-graph-data-url");
    var bg = el.getAttribute("data-tui-graph-bg") || "transparent";
    var colorMap = JSON.parse(
      el.getAttribute("data-tui-graph-color-map") || "{}"
    );
    var enableExpand =
      el.getAttribute("data-tui-graph-expand") === "true";
    var expandURL =
      el.getAttribute("data-tui-graph-expand-url") || "";
    var controlType =
      el.getAttribute("data-tui-graph-control") || "trackball";
    var onClick = el.getAttribute("data-tui-graph-on-click") || "";
    var clickURL =
      el.getAttribute("data-tui-graph-click-url") || "";

    var mount = el.querySelector("[data-tui-graph-mount]");
    if (!mount) throw new Error("no [data-tui-graph-mount] element");

    // 3d-force-graph 1.73 is a kapsule factory: ForceGraph3D(config)
    // returns the component, which is then called with its element.
    // (new ForceGraph3D(el, config) is the 1.74+ form; on 1.73 it
    // returns a component that never attaches.)
    var graph = ForceGraph3D({ controlType: controlType })(mount)
      .backgroundColor(
        bg === "transparent" ? "rgba(0,0,0,0)" : bg
      )
      .nodeColor(function (n) {
        return getColor(colorMap, n.type);
      })
      .nodeVal(function (n) {
        return n.val || 1;
      })
      .nodeLabel(function (n) {
        return n.name || n.id;
      })
      .linkWidth(1)
      .linkOpacity(0.4)
      .linkDirectionalArrowLength(3.5)
      .linkDirectionalArrowRelPos(1)
      .onNodeClick(function (node, event) {
        el.dispatchEvent(
          new CustomEvent("tui-graph-node-click", {
            detail: { node: node },
            bubbles: true,
          })
        );
        if (onClick === "slideover" && clickURL) {
          var url = clickURL.replace("{id}", node.id);
          if (typeof htmx !== "undefined") {
            htmx.ajax("GET", url, {
              target: "#slide-over-body",
              swap: "innerHTML",
            });
          }
          document.dispatchEvent(
            new CustomEvent("slideover-open", { detail: {} })
          );
        } else if (onClick === "navigate" && clickURL) {
          window.location.href = clickURL.replace("{id}", node.id);
        } else if (
          onClick &&
          typeof window[onClick] === "function"
        ) {
          window[onClick](node, event);
        }

        // Expand neighbors on click if enabled
        if (enableExpand && expandURL) {
          expandNeighbors(id, node.id, expandURL, colorMap);
        }
      })
      .onNodeHover(function (node) {
        el.style.cursor = node ? "pointer" : "default";
        if (node) {
          el.dispatchEvent(
            new CustomEvent("tui-graph-node-hover", {
              detail: { node: node },
              bubbles: true,
            })
          );
        }
      });

    // The component draws into a <canvas> as soon as it is attached; no
    // canvas means the library was called the wrong way for its version.
    if (!mount.querySelector("canvas")) {
      throw new Error("3d-force-graph attached no canvas");
    }

    // Fit to view when engine settles
    graph.onEngineStop(function () {
      graph.zoomToFit(400);
    });

    instances.set(id, {
      graph: graph,
      data: null,
      cleanup: function () {
        if (graph._destructor) graph._destructor();
      },
    });

    // Check for pending data (inline mode)
    if (pendingData.has(id)) {
      var data = pendingData.get(id);
      pendingData.delete(id);
      setData(id, data);
    } else if (dataURL) {
      fetch(dataURL)
        .then(function (r) {
          if (!r.ok) throw new Error("HTTP " + r.status + " from " + dataURL);
          return r.json();
        })
        .then(function (data) {
          setData(id, data);
        })
        .catch(function (err) {
          showError(el, "Failed to load graph: " + (err && err.message ? err.message : err), err);
        });
    }

    // Responsive sizing
    var ro = new ResizeObserver(function () {
      graph.width(mount.clientWidth).height(mount.clientHeight);
    });
    ro.observe(mount);
  }

  function expandNeighbors(graphId, nodeId, expandURLPrefix, colorMap) {
    var inst = instances.get(graphId);
    if (!inst) return;

    var existingIds = new Set(
      inst.graph.graphData().nodes.map(function (n) {
        return n.id;
      })
    );
    var url =
      expandURLPrefix +
      "?node_id=" +
      nodeId +
      "&exclude=" +
      Array.from(existingIds).join(",");

    fetch(url)
      .then(function (r) {
        return r.json();
      })
      .then(function (newData) {
        var current = inst.graph.graphData();
        var mergedNodes = current.nodes.slice();
        var mergedLinks = current.links.slice();
        var nodeSet = new Set(
          current.nodes.map(function (n) {
            return n.id;
          })
        );

        (newData.nodes || []).forEach(function (n) {
          if (!nodeSet.has(n.id)) {
            mergedNodes.push(n);
            nodeSet.add(n.id);
          }
        });
        (newData.links || []).forEach(function (l) {
          mergedLinks.push(l);
        });

        inst.graph.graphData({
          nodes: mergedNodes,
          links: mergedLinks,
        });
      })
      .catch(function (err) {
        console.error("Expand neighbors failed:", err);
      });
  }

  function setData(graphId, data) {
    var inst = instances.get(graphId);
    if (inst) {
      var el = document.getElementById(graphId);
      try {
        inst.graph.graphData(checkData(data));
      } catch (err) {
        if (el) showError(el, "Invalid graph data: " + err.message, err);
        else console.error("graphwidget #" + graphId + ": invalid graph data", err);
        return;
      }
      inst.data = data;
      if (el) {
        var loading = el.querySelector("[data-tui-graph-loading]");
        if (loading) loading.style.display = "none";
        el.setAttribute("data-tui-graph-ready", "true");
      }
    } else {
      pendingData.set(graphId, data);
    }
  }

  function destroy(graphId) {
    var inst = instances.get(graphId);
    if (inst) {
      inst.cleanup();
      instances.delete(graphId);
    }
  }

  function getInstance(graphId) {
    return instances.get(graphId);
  }

  // Initialize on DOM ready and after HTMX swaps
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
  document.addEventListener("htmx:afterSwap", init);

  // MutationObserver for dynamically added graphs
  new MutationObserver(function (mutations) {
    for (var i = 0; i < mutations.length; i++) {
      var addedNodes = mutations[i].addedNodes;
      for (var j = 0; j < addedNodes.length; j++) {
        var n = addedNodes[j];
        if (
          n.nodeType === 1 &&
          (n.hasAttribute && n.hasAttribute("data-tui-graph") ||
            n.querySelector && n.querySelector("[data-tui-graph]"))
        ) {
          setTimeout(init, 0);
          return;
        }
      }
    }
  }).observe(document.body, { childList: true, subtree: true });

  window.tui = window.tui || {};
  window.tui.graph = {
    init: init,
    destroy: destroy,
    setData: setData,
    getInstance: getInstance,
  };
})();
